const bank = "NUBANK";
const linhas = $input.item.json.lines;


// =========================================================
// 2. CLIENTE
// =========================================================

const clientName = linhas[0];


// =========================================================
// 3. CONFIGURAÇÕES
// =========================================================

const meses = {
  JAN: "01",
  FEV: "02",
  MAR: "03",
  ABR: "04",
  MAI: "05",
  JUN: "06",
  JUL: "07",
  AGO: "08",
  SET: "09",
  OUT: "10",
  NOV: "11",
  DEZ: "12"
};


// Data de movimentação
const regexData =
  /^(\d{2})\s+(JAN|FEV|MAR|ABR|MAI|JUN|JUL|AGO|SET|OUT|NOV|DEZ)\s+(\d{4})\b/i;


// Valor
const regexValor =
  /^\d{1,3}(?:\.\d{3})*,\d{2}$/;


// Valor no final da linha
const regexValorFinal =
  /(\d{1,3}(?:\.\d{3})*,\d{2})$/;


// =========================================================
// 4. IDENTIFICAR LINHAS DE RESUMO / RODAPÉ
// =========================================================

function ehResumoOuRodape(linha) {

  const texto = linha
    .toUpperCase()
    .replace(/\s+/g, " ")
    .trim();


  // -------------------------------------------------------
  // RESUMO DA CONTA
  // -------------------------------------------------------

  if (
    texto.includes("SALDO INICIAL") ||
    texto.includes("RENDIMENTO LÍQUIDO") ||
    texto.includes("SALDO FINAL DO PERÍODO") ||
    texto.includes("TOTAL DE ENTRADAS") ||
    texto.includes("TOTAL DE SAÍDAS")
  ) {
    return true;
  }


  // -------------------------------------------------------
  // TEXTOS LEGAIS / RODAPÉ
  // -------------------------------------------------------

  if (
    texto.includes("O SALDO LÍQUIDO CORRESPONDE") ||
    texto.includes("NÃO NOS RESPONSABILIZAMOS") ||
    texto.includes("ASSEGURAMOS A AUTENTICIDADE") ||
    texto.includes("NU FINANCEIRA S.A.") ||
    texto.includes("NU PAGAMENTOS S.A.") ||
    texto.includes("SOCIEDADE DE CREDITO") ||
    texto.includes("INSTITUIÇÃO DE PAGAMENTO") ||
    texto.includes("CNPJ:")
  ) {
    return true;
  }


  // -------------------------------------------------------
  // RODAPÉ DO DOCUMENTO
  // -------------------------------------------------------

  if (
    texto.includes("TEM ALGUMA DÚVIDA") ||
    texto.includes("MANDE UMA MENSAGEM") ||
    texto.includes("ATENDIMENTO 24H") ||
    texto.includes("DISPONÍVEIS EM NUBANK.COM.BR") ||
    texto.includes("ATENDIMENTO DAS 8H ÀS 18H") ||
    texto.includes("EXTRATO GERADO DIA")
  ) {
    return true;
  }


  // -------------------------------------------------------
  // PAGINAÇÃO
  // -------------------------------------------------------

  if (/^\d+\s+DE\s+\d+$/.test(texto)) {
    return true;
  }


  return false;
}


// =========================================================
// 5. DETERMINAR TIPO
// =========================================================

function determinarTipo(descricao) {

  const texto = descricao.toUpperCase();


  // Entradas
  if (
    texto.includes("TRANSFERÊNCIA RECEBIDA") ||
    texto.includes("CRÉDITO EM CONTA") ||
    texto.includes("VALOR ADICIONADO") ||
    texto.includes("REEMBOLSO RECEBIDO") ||
    texto.includes("RESGATE RDB") ||
    texto.includes("RENDIMENTO") ||
    texto.includes("DEPÓSITO DE EMPRÉSTIMO")
  ) {
    return "ENTRADA";
  }


  // Saídas
  return "SAIDA";
}

// =========================================================
// 5.1 LIMPAR DESCRIÇÃO
// =========================================================

function limparDescricao(descricao) {

  descricao = descricao
    .replace(/\s+/g, " ")
    .trim();

  // Procura o início real de uma movimentação.
  // Tudo que vier antes será descartado.
  const regexInicioMovimentacao =
    /(Transferência|Compra|Pagamento|Aplicação RDB|Resgate RDB|Crédito em conta|Valor adicionado|Reembolso|Pix|Depósito|Estorno|Tarifa|TED|DOC|Boleto)/i;

  const match = descricao.match(regexInicioMovimentacao);

  if (match) {
    descricao = descricao.substring(match.index).trim();
  }

  return descricao;
}


// =========================================================
// 6. AGRUPAR POR DATA
// =========================================================

const dias = [];

let diaAtual = null;

for (const linha of linhas) {

  const match = linha.match(regexData);

  if (match) {

    const [, dia, mesTexto, ano] = match;

    diaAtual = {
      data: `${dia}/${meses[mesTexto.toUpperCase()]}/${ano}`,
      linhas: []
    };

    dias.push(diaAtual);

    continue;
  }

  if (diaAtual) {
    diaAtual.linhas.push(linha);
  }
}


// =========================================================
// 7. EXTRAIR TRANSAÇÕES
// =========================================================

const transacoes = [];


for (const dia of dias) {

  let descricaoAtual = [];

  let bloqueado = false;


  // -------------------------------------------------------
  // FINALIZAR TRANSAÇÃO
  // -------------------------------------------------------

  function finalizarTransacao(valor) {

    if (descricaoAtual.length === 0) {
      return;
    }


    const descricao = limparDescricao(
  descricaoAtual.join(" ")
);


    // Não aceitar descrições de resumo
    if (ehResumoOuRodape(descricao)) {

      descricaoAtual = [];

      return;
    }


    // Não aceitar descrições extremamente pequenas
    if (
      descricao === "+" ||
      descricao === "-" ||
      descricao === "C" ||
      descricao === "D"
    ) {

      descricaoAtual = [];

      return;
    }


    // -----------------------------------------------------
    // CRIAR TRANSAÇÃO
    // -----------------------------------------------------

    transacoes.push({
      data: dia.data,
      documento: "",
      descricao: limparDescricao(descricao),
      valor,
      tipoTransacao: determinarTipo(descricao)
    });


    descricaoAtual = [];
  }


  // -------------------------------------------------------
  // PERCORRER LINHAS
  // -------------------------------------------------------

  for (const linha of dia.linhas) {


    // -----------------------------------------------------
    // SE ENCONTROU RESUMO, BLOQUEIA O RESTANTE DO DIA
    // -----------------------------------------------------

    if (ehResumoOuRodape(linha)) {

      descricaoAtual = [];

      // Se for resumo financeiro, não queremos
      // interpretar os valores que aparecem depois.
      if (
        linha.toUpperCase().includes("SALDO INICIAL") ||
        linha.toUpperCase().includes("SALDO FINAL") ||
        linha.toUpperCase().includes("RENDIMENTO LÍQUIDO")
      ) {
        bloqueado = true;
      }

      continue;
    }


    // Depois do resumo, ignora tudo
    if (bloqueado) {
      continue;
    }


    // -----------------------------------------------------
    // VALOR SOZINHO
    // -----------------------------------------------------

    if (regexValor.test(linha)) {

      finalizarTransacao(linha);

      continue;
    }


    // -----------------------------------------------------
    // DESCRIÇÃO + VALOR
    // -----------------------------------------------------

    const matchValor = linha.match(regexValorFinal);

    if (matchValor) {

      const valor = matchValor[1];

      const descricao = linha
        .slice(0, matchValor.index)
        .trim();


      // Se havia linhas anteriores, elas pertencem
      // à transação atual.
      if (descricaoAtual.length > 0) {

        descricaoAtual.push(descricao);

        finalizarTransacao(valor);

        continue;
      }


      // Caso seja uma transação completa em uma linha
      if (descricao) {

        // Não aceitar sinais isolados
        if (
          descricao !== "+" &&
          descricao !== "-"
        ) {

          transacoes.push({
            data: dia.data,
            documento: "",
            descricao,
            valor,
            tipoTransacao: determinarTipo(descricao)
          });
        }
      }

      continue;
    }


    // -----------------------------------------------------
    // CONTINUAÇÃO DA DESCRIÇÃO
    // -----------------------------------------------------

    descricaoAtual.push(linha);
  }


  // Limpa qualquer resto
  descricaoAtual = [];
}


// =========================================================
// 8. RETORNO
// =========================================================

let count = transacoes.length;

return {
  bank,
  clientName,
  count,
  transacoes
};
